export const clamp=(v,a=0,b=1)=>Math.min(b,Math.max(a,v));
const defaults={midpoint:50,feather:65,grainSize:1,grainRoughness:50,radius:1,keyTolerance:35,keyFeather:8,gradingBlending:50};
export const fresh=()=>({values:{},curves:{rgb:[[0,0],[1,1]],r:[[0,0],[1,1]],g:[[0,0],[1,1]],b:[[0,0],[1,1]]},hsl:Array.from({length:8},()=>({h:0,s:0,l:0})),grading:{shadows:{h:0,s:0,l:0},midtones:{h:0,s:0,l:0},highlights:{h:0,s:0,l:0},global:{h:0,s:0,l:0}},crop:[0,0,1,1],turns:0,flipX:false,flipY:false,cutout:false,portrait:0,subjectX:0,subjectY:0,subjectScale:1,edge:0,background:{type:'transparent'},masks:[]});
export const copy=x=>structuredClone(x);
export const get=(p,k)=>Number.isFinite(p.values?.[k])?p.values[k]:(defaults[k]??0);
const linear=x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4;
const encoded=x=>x<=.0031308?x*12.92:1.055*Math.max(0,x)**(1/2.4)-.055;
const luma=(r,g,b)=>r*.2126+g*.7152+b*.0722;
const smooth=(a,b,x)=>{const t=clamp((x-a)/(Math.abs(b-a)<1e-9?1:b-a));return t*t*(3-2*t)};
export function rgbToHsl(r,g,b){const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn,l=(mx+mn)/2;if(d<1e-8)return[0,0,l];let h=mx===r?((g-b)/d)%6:mx===g?(b-r)/d+2:(r-g)/d+4;return[(h*60+360)%360,d/(1-Math.abs(2*l-1)),l]}
export function hslToRgb(h,s,l){h=((h%360)+360)%360;const c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2;const v=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return v.map(v=>v+m)}
function points(list){return (list??[[0,0],[1,1]]).map(p=>Array.isArray(p)?p:[p.x,p.y]).sort((a,b)=>a[0]-b[0])}
function curveTable(list){const ps=points(list),out=new Float32Array(4096);for(let i=0;i<4096;i++){let x=i/4095,y=ps.at(-1)[1];if(x<=ps[0][0])y=ps[0][1];else for(let j=1;j<ps.length;j++)if(x<=ps[j][0]){y=ps[j-1][1]+(ps[j][1]-ps[j-1][1])*(x-ps[j-1][0])/Math.max(.000001,ps[j][0]-ps[j-1][0]);break}out[i]=y}return out}
export function prepare(recipe){const p=recipe??fresh();return{p,luts:Object.fromEntries(['rgb','r','g','b'].map(k=>[k,curveTable(p.curves?.[k])])),hasHsl:p.hsl?.some(a=>a.h||a.s||a.l),hasGrade:Object.values(p.grading??{}).some(a=>a.s||a.l)}}
export function shade(r,g,b,ctx){const {p,luts,hasHsl,hasGrade}=ctx;
 const exposure=2**clamp(get(p,'exposure'),-5,5),contrast=1+get(p,'contrast')/200,high=get(p,'highlights')/100,shadow=get(p,'shadows')/100,whites=get(p,'whites')/100,blacks=get(p,'blacks')/100,temp=get(p,'temperature'),tint=get(p,'tint');
 let lr=linear(r),lg=linear(g),lb=linear(b),l=luma(lr,lg,lb),sw=1-smooth(.02,.42,l),hw=smooth(.2,.95,l),tone=exposure*2**(shadow*sw*.65+high*hw*.65+whites*hw*hw*.45+blacks*sw*sw*.45);
 lr*=tone*(1+temp/400+tint/800);lg*=tone*(1-tint/500);lb*=tone*(1-temp/400+tint/800);
 r=clamp(encoded((lr-.18)*contrast+.18));g=clamp(encoded((lg-.18)*contrast+.18));b=clamp(encoded((lb-.18)*contrast+.18));
 const av=luma(r,g,b),range=Math.max(r,g,b)-Math.min(r,g,b),sat=Math.max(0,1+get(p,'saturation')/100+get(p,'vibrance')/100*(1-range));r=clamp(av+(r-av)*sat);g=clamp(av+(g-av)*sat);b=clamp(av+(b-av)*sat);
 if(hasHsl){let[hh,ss,ll]=rgbToHsl(r,g,b),dh=0,ds=0,dl=0;[0,30,60,120,180,240,275,315].forEach((center,j)=>{let dist=Math.min(Math.abs(hh-center),360-Math.abs(hh-center)),w=Math.max(0,1-dist/42);dh+=p.hsl[j].h*w*.5;ds+=p.hsl[j].s*w/100;dl+=p.hsl[j].l*w/200});[r,g,b]=hslToRgb(hh+dh,clamp(ss*(1+ds)),clamp(ll+dl*ss))}
 if(hasGrade){let y=luma(r,g,b),bal=get(p,'gradingBalance')/300,blend=clamp(get(p,'gradingBlending')/100,.01,1);for(let[zone,a]of Object.entries(p.grading)){let w=zone==='shadows'?1-smooth(.1+bal,.5+bal,y):zone==='midtones'?1-Math.abs(y-.5)*2:zone==='highlights'?smooth(.45+bal,.95+bal,y):1;let[cr,cg,cb]=hslToRgb(a.h,1,.5),s=a.s/100*w*(.1+.25*blend),ll=a.l/300*w;r=clamp(r+(cr-.5)*s+ll);g=clamp(g+(cg-.5)*s+ll);b=clamp(b+(cb-.5)*s+ll)}}
 const lookup=(a,x)=>a[Math.round(clamp(x)*4095)];r=lookup(luts.r,lookup(luts.rgb,r));g=lookup(luts.g,lookup(luts.rgb,g));b=lookup(luts.b,lookup(luts.rgb,b));let dh=get(p,'dehaze')/500;if(dh){r=clamp((r-dh)/(1-2*dh));g=clamp((g-dh)/(1-2*dh));b=clamp((b-dh)/(1-2*dh))}return[r,g,b];
}
export function makeLut(recipe){const n=16,w=256,h=16,out=new Uint8Array(w*h*4),ctx=prepare(recipe);for(let b=0;b<n;b++)for(let g=0;g<n;g++)for(let r=0;r<n;r++){let rgb=shade(r/15,g/15,b/15,ctx),i=(g*w+b*16+r)*4;out[i]=Math.round(clamp(rgb[0])*255);out[i+1]=Math.round(clamp(rgb[1])*255);out[i+2]=Math.round(clamp(rgb[2])*255);out[i+3]=255}return out}
const spatial=new Set(['rotation','quarterTurns','flipX','flipY','vertical','horizontal','blur','portraitBlur','subjectX','subjectY','subjectScale','subjectCutout','subjectEdge','keyEnabled','keyTolerance','keyFeather']);
export function applyPreset(current,base,preset,amount=1){const target=preset.recipe??preset,next=copy(current);let keys=new Set([...Object.keys(base.values??{}),...Object.keys(target.values??{}),...Object.keys(defaults)]);for(let key of keys)if(!spatial.has(key))next.values[key]=get(base,key)+(get(target,key)-get(base,key))*amount;
 const blend=(a,b)=>a+(b-a)*amount;next.hsl=base.hsl.map((v,i)=>({h:blend(v.h,target.hsl[i].h),s:clamp(blend(v.s,target.hsl[i].s),-100,100),l:clamp(blend(v.l,target.hsl[i].l),-100,100)}));next.grading=Object.fromEntries(Object.entries(base.grading).map(([zone,v])=>[zone,{h:blend(v.h,target.grading[zone].h),s:clamp(blend(v.s,target.grading[zone].s),0,100),l:clamp(blend(v.l,target.grading[zone].l),-100,100)}]));
 const at=(list,x)=>{const ps=points(list);if(x<=ps[0][0])return ps[0][1];for(let i=1;i<ps.length;i++)if(x<=ps[i][0])return ps[i-1][1]+(ps[i][1]-ps[i-1][1])*(x-ps[i-1][0])/Math.max(.000001,ps[i][0]-ps[i-1][0]);return ps.at(-1)[1]};for(let key of ['rgb','r','g','b'])next.curves[key]=amount===0?copy(base.curves[key]):amount===1?copy(target.curves[key]):Array.from({length:17},(_,i)=>[i/16,clamp(blend(at(base.curves[key],i/16),at(target.curves[key],i/16)))]);return next}
export function moveCrop(b,dx,dy){return[clamp(b[0]+dx,0,1-b[2]),clamp(b[1]+dy,0,1-b[3]),b[2],b[3]]}
export function resizeCrop(b,handle,dx,dy,ratio=0){let[l,t,w,h]=b,r=l+w,bt=t+h,W=handle.includes('w'),E=handle.includes('e'),N=handle.includes('n'),S=handle.includes('s');if(W)l=clamp(l+dx,0,r-.02);if(E)r=clamp(r+dx,l+.02,1);if(N)t=clamp(t+dy,0,bt-.02);if(S)bt=clamp(bt+dy,t+.02,1);if(ratio>0){let ax=W?b[0]+b[2]:E?b[0]:b[0]+b[2]/2,ay=N?b[1]+b[3]:S?b[1]:b[1]+b[3]/2;w=r-l;h=bt-t;if((W||E)&&(!(N||S)||Math.abs(dx)>=Math.abs(dy)))h=w/ratio;else w=h*ratio;let maxW=W?ax:E?1-ax:2*Math.min(ax,1-ax),maxH=N?ay:S?1-ay:2*Math.min(ay,1-ay),fit=Math.min(1,maxW/w,maxH/h);w*=fit;h*=fit;l=W?ax-w:E?ax:ax-w/2;t=N?ay-h:S?ay:ay-h/2;r=l+w;bt=t+h}return[l,t,Math.max(.001,r-l),Math.max(.001,bt-t)]}
export function outputSize(w,h,recipe,limit=0,maxPixels=12000000){let ow=Math.max(1,Math.round(w*recipe.crop[2])),oh=Math.max(1,Math.round(h*recipe.crop[3]));if(recipe.turns%2)[ow,oh]=[oh,ow];let scale=Math.min(1,Math.sqrt(maxPixels/(ow*oh)),limit>0?limit/Math.max(ow,oh):1);return[Math.max(1,Math.round(ow*scale)),Math.max(1,Math.round(oh*scale))]}
